import re
from typing import Dict, List, Set, Tuple

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    sections = {}
    current_section = None
    default_section = {}
    lines = text.splitlines()
    current_value = []
    in_quotes = False

    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line[0] in ("#", ";"):
            in_quotes = False
            continue
        if line[0] == "[":
            match = re.match(r"\[(.*?)\]", line)
            if match:
                section_name = match.group(1).strip().lower()
                if section_name == "default":
                    current_section = section_name
                    sections[section_name] = default_section
                    continue
                elif section_name in sections:
                    current_section = section_name
                else:
                    current_value = []
                    in_quotes = False
                    continue
            else:
                raise ValueError(f"Invalid section name: {line}")
        else:
            if current_section is None:
                raise ValueError(f"Key line before section header: {line}")
            parts = re.split(r"([=:])(\s*)", line, maxsplit=1)
            if len(parts) != 3:
                raise ValueError(f"Malformed line: {line}")
            key, sep, value = parts
            key = key.strip().lower()
            if sep == "=" or sep == ":":
                value = value.strip()
                if value and value[0] == '"' and value[-1] == '"':
                    in_quotes = not in_quotes
                    value = value[1:-1]
                if in_quotes:
                    current_value.append(value)
                else:
                    current_value.append(value.replace("\\n", "\n"))
            else:
                if not current_value:
                    raise ValueError(f"Invalid continuation: {line}")
                current_value.append(value.replace("\\n", "\n"))

        if not current_value:
            continue
        if in_quotes:
            current_value.append(current_value.pop())
        current_value = "".join(current_value).strip()
        if in_quotes:
            in_quotes = False
        if current_section == "default":
            default_section[key] = current_value
        elif key in sections[current_section]:
            sections[current_section][key] = current_value
        else:
            sections[current_section][key] = current_value

    interpolate(sections)

    return sections

def interpolate(sections: Dict[str, Dict[str, str]]) -> None:
    for section_name, section in sections.items():
        for key, value in section.items():
            if value.startswith("${") and value.endswith("}"):
                match = re.match(r"\${(.*?)\}", value)
                if match:
                    key_name = match.group(1).split(":")
                    if len(key_name) == 2:
                        section_name, key_name = key_name
                    else:
                        section_name = key_name[0]
                    if section_name == "default":
                        new_value = sections[section_name].get(key_name, "")
                    else:
                        new_value = sections.get(section_name, {}).get(key_name, "")
                    if new_value == "${" + key_name[0] + ":" + key_name[1] + "}":
                        raise ValueError(f"Reference cycle: {value}")
                    value = str(new_value)
                    section[key] = value
                    interpolate({section_name: sections[section_name]})  # Recursively interpolate
            section[key] = value.replace("\\n", "\n")

            if value.startswith("${"):
                raise KeyError(f"Missing key: {value}")
