from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.stats = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}
        self.cache = OrderedDict()

    def put(self, key, value):
        now = self.clock()
        if self.capacity == 0:
            return
        if key in self.cache:
            self.cache[key] = (now, value)
        else:
            if len(self.cache) >= self.capacity:
                self._gc(now)
            self.cache[key] = (now, value)

    def get(self, key, default=None):
        now = self.clock()
        if key not in self.cache:
            self.stats["misses"] += 1
            return default
        (expiry, value), _ = self.cache.pop(key)
        self.stats["hits"] += 1
        if now >= expiry:
            self.stats["expirations"] += 1
        else:
            self.cache[key] = (expiry, value)
        return value

    def __len__(self):
        now = self.clock()
        return sum(1 for (expiry, _) in self.cache.values() if now < expiry)

    def _gc(self, now):
        while len(self.cache) > self.capacity and any(now >= expiry for (_, (_, expiry)) in self.cache.items()):
            self.stats["evictions"] += 1
            self.stats["expirations"] += 1
            self.cache.popitem(last=False)

    def stats(self):
        return self.stats.copy()

# Example usage:
import time

def clock():
    return time.time()

cache = TTLCache(10, 10, clock)
print(len(cache))  # prints the number of entries not expired
print(cache.stats())  # prints {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}
